//! Guards the layout the CPU side uploads.
//!
//! `GpuPrimitive` is uploaded straight into the buffer or data texture the SDF shaders read. The
//! shaders' `Primitive` is generated by russl from `sdf_russl::primitive`, and the in-crate
//! `russl_parity` tests check it against `GpuPrimitive` field for field. These do not need a GPU.

use naga::TypeInner;

/// Parsed from the source rather than hand-listed, so it cannot go stale.
fn rust_primitive_fields() -> Vec<(String, String)> {
    let src = include_str!("../src/primitives.rs");
    let start = src
        .find("pub struct GpuPrimitive {")
        .expect("no GpuPrimitive declaration");
    let body_start = src[start..].find('{').unwrap() + start + 1;
    let body_end = src[body_start..].find("\n}").unwrap() + body_start;

    let mut out = Vec::new();
    for line in src[body_start..body_end].lines() {
        let line = line.trim();
        if !line.starts_with("pub ") {
            continue;
        }
        let line = line.trim_start_matches("pub ").trim_end_matches(',');
        if let Some((name, ty)) = line.split_once(':') {
            out.push((name.trim().to_string(), ty.trim().to_string()));
        }
    }
    out
}

#[test]
fn data_texture_rows_hold_every_primitive_field() {
    let texels = blinc_gpu::GpuPrimitive::DATA_TEXTURE_TEXELS as usize;
    assert_eq!(texels, rust_primitive_fields().len());
    assert_eq!(
        texels * std::mem::size_of::<[f32; 4]>(),
        std::mem::size_of::<blinc_gpu::GpuPrimitive>()
    );
}

fn wgsl_definition(src: &str, marker: &str) -> String {
    let start = src.find(marker).unwrap();
    let end = src[start..].find("\n}").unwrap() + start + 2;
    src[start..end].to_string()
}
#[test]
fn glass_uniform_layout_keeps_tight_target_and_backdrop_frames_separate() {
    use blinc_gpu::primitives::GlassUniforms;
    assert_eq!(std::mem::size_of::<GlassUniforms>(), 32);
    assert_eq!(std::mem::offset_of!(GlassUniforms, sample_size), 16);
    assert_eq!(std::mem::offset_of!(GlassUniforms, origin), 24);
    for (name, source, declaration) in [
        (
            "glass",
            include_str!("../src/shaders/glass.wgsl"),
            "struct GlassUniforms {",
        ),
        (
            "glass_dt",
            include_str!("../src/shaders/glass_dt.wgsl"),
            "struct GlassUniforms {",
        ),
        (
            "simple_glass",
            include_str!("../src/shaders/simple_glass.wgsl"),
            "struct SimpleGlassUniforms {",
        ),
        (
            "simple_glass_dt",
            include_str!("../src/shaders/simple_glass_dt.wgsl"),
            "struct SimpleGlassUniforms {",
        ),
    ] {
        let definition = wgsl_definition(source, declaration);
        let module = naga::front::wgsl::parse_str(&definition).unwrap();
        let members = module
            .types
            .iter()
            .find_map(|(_, ty)| match &ty.inner {
                TypeInner::Struct { members, span } => Some((members, span)),
                _ => None,
            })
            .unwrap();
        assert_eq!(*members.1, 32, "{name}");
        assert_eq!(
            members
                .0
                .iter()
                .map(|m| (m.name.as_deref().unwrap(), m.offset))
                .collect::<Vec<_>>(),
            vec![
                ("viewport_size", 0),
                ("time", 8),
                ("clip_in_image", 12),
                ("sample_size", 16),
                ("origin", 24)
            ],
            "{name}"
        );
    }
}
